import os
from dataclasses import dataclass, field
from typing import Optional, Union

from dotenv import load_dotenv
from transformers import TrainingArguments
from trl import SFTConfig

from psalm.utils.env_utils import get_env_by_name_or_default, get_list_env_by_name_or_default

load_dotenv()

@dataclass
class TrainerConfig(SFTConfig, TrainingArguments):
    output_dir: Optional[str] = field(default_factory=lambda: get_env_by_name_or_default("OUTPUT_DIR", "trainer_outputs", str))
    overwrite_output_dir: Optional[bool] = field(default_factory=lambda: get_env_by_name_or_default("OVERWRITE_OUTPUT_DIR", False, bool))
    eval_strategy: Optional[str] = field(default_factory=lambda: get_env_by_name_or_default("EVAL_STRATEGY", "no", str))
    prediction_loss_only: Optional[bool] = field(default_factory=lambda: get_env_by_name_or_default("PREDICTION_LOSS_ONLY", False, bool))
    per_device_train_batch_size:  Optional[int] = field(default_factory=lambda: get_env_by_name_or_default("PER_DEVICE_TRAIN_BATCH_SIZE", 8, int))
    per_device_eval_batch_size:  Optional[int] = field(default_factory=lambda: get_env_by_name_or_default("PER_DEVICE_EVAL_BATCH_SIZE", 8, int))
    gradient_accumulation_steps:  Optional[int] = field(default_factory=lambda: get_env_by_name_or_default("GRADIENT_ACCUMULATION_STEPS", 1, int))
