    adam_beta1: Optional[float] = field(default_factory=lambda: get_env_by_name_or_default("ADAM_BETA1", 0.9, float))
    adam_beta2: Optional[float] = field(default_factory=lambda: get_env_by_name_or_default("ADAM_BETA2", 0.999, float))
