    use_cpu: Optional[bool] = field(default_factory=lambda: get_env_by_name_or_default("USE_CPU", False, bool))
    seed: Optional[int] = field(default_factory=lambda: get_env_by_name_or_default("SEED", 42, int))
    data_seed: Optional[int] = field(default_factory=lambda: get_env_by_name_or_default("DATA_SEED", None, int))
