    deepspeed: Optional[str] = field(default_factory=lambda: get_env_by_name_or_default("DEEPSPEED", None, str))
    debug: Optional[str] = field(default_factory=lambda: get_env_by_name_or_default("DEBUG", "", str))
    optim: Optional[str] = field(default_factory=lambda: get_env_by_name_or_default("OPTIM", "adamw_torch", str))
    optim_args: Optional[str] = field(default_factory=lambda: get_env_by_name_or_default("OPTIM_ARGS", None, str))
    report_to: Optional[str] = field(default_factory=lambda: get_env_by_name_or_default("REPORT_TO", "all", str))
    dataloader_pin_memory: Optional[bool] = field(default_factory=lambda: get_env_by_name_or_default("DATALOADER_PIN_MEMORY", True, bool))
    dataloader_persistent_workers: Optional[bool] = field(default_factory=lambda: get_env_by_name_or_default("DATALOADER_PERSISTENT_WORKERS", False, bool))
