    auto_find_batch_size: Optional[bool] = field(default_factory=lambda: get_env_by_name_or_default("AUTO_FIND_BATCH_SIZE", False, bool))
    full_determinism: Optional[bool] = field(default_factory=lambda: get_env_by_name_or_default("FULL_DETERMINISM", False, bool))
