    eos_token: Optional[str] = field(default_factory=lambda: get_env_by_name_or_default("EOS_TOKEN", None, str))
    pad_token: Optional[int] = field(default_factory=lambda: get_env_by_name_or_default("PAD_TOKEN", None, int))
    max_length: Optional[int] = field(default_factory=lambda: get_env_by_name_or_default("MAX_LENGTH", None, int))
    packing: Optional[bool] = field(default_factory=lambda: get_env_by_name_or_default("PACKING", False, bool))
    packing_strategy: Optional[str] = field(default_factory=lambda: get_env_by_name_or_default("PACKING_STRATEGY", "bfd", str))
    padding_free: Optional[bool] = field(default_factory=lambda: get_env_by_name_or_default("PADDING_FREE", False, bool))
    pad_to_multiple_of: Optional[int] = field(default_factory=lambda: get_env_by_name_or_default("PAD_TO_MULTIPLE_OF", None, int))
    eval_packing: Optional[bool] = field(default_factory=lambda: get_env_by_name_or_default("EVAL_PACKING", False, bool))
    completion_only_loss: Optional[bool] = field(default_factory=lambda: get_env_by_name_or_default("COMPLETION_ONLY_LOSS", False, bool))
    assistant_only_loss: Optional[bool] = field(default_factory=lambda: get_env_by_name_or_default("ASSISTANT_ONLY_LOSS", False, bool))
